mapper.select:
SELECT  num,a.*
from (
	select t.*,ROW_NUMBER() over() num from (







		UNION ALL




	/***update by leipeng 20190824**/
	) t order by mdateUnadjust desc,nvl(adjustNum,0) desc
) a

mapper.sql:
select FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, NULL AS adjusttype, FP.MDATE mdateUnadjust, FP.LIQUIDATION_DATE ldateUnadjust, NULL AS ldate, NULL AS bdate, NULL AS rdate, NULL AS mdate, NULL AS remark, FP.FINPROD_ID finprodId, NULL AS adjustNum, NULL AS status, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO_AUTHORITY PPA, FIN_PRODUCT FP LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FP.FINPROD_ID = PMSI.FINPROD_ID where FP.FINPROD_ID = FPA.FINPROD_ID and FPA.PORTFOLIO_ID = PPA.PORTFOLIO_ID and PPA.USER_ID = #{userId} and FP.FINPROD_TYPE2 = #{finprodType2} and FP.P_FINPROD_ID IS NULL and FP.MDATE > #{platDate} and FPA.ISSUE_STATUS = #{ISSUE_STATUS01}
and FP.FINPROD_ID IN
#{item}
AND NVL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
and not exists (select 1 from PRD_MDATE_ADJUST where FP.FINPROD_ID = PRD_MDATE_ADJUST.FINPROD_ID)

select FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, PMAD.ADJUST_TYPE adjusttype, PMAD.MDATE_UNADJUST mdateUnadjust, PMAD.LDATE_UNADJUST ldateUnadjust,
PMAD.LDATE ldate, decode(PMAD.ADJUST_TYPE,#{TZLX_TQZZ},PMAD.MDATE,NULL) bdate, decode(PMAD.ADJUST_TYPE,#{TZLX_CPZQ},PMAD.MDATE,NULL) rdate, decode(PMAD.ADJUST_TYPE,#{TZLX_DQRTZ},PMAD.MDATE,NULL) mdate, PMAD.REMARK remark, FP.FINPROD_ID finprodId, PMAD.ADJUST_NUM adjustNum, decode(PMAD.ADJUST_NUM ,(select max(ADJUST_NUM) from PRD_MDATE_ADJUST pma where pma.FINPROD_ID=PMAD.FINPROD_ID),'E','D') status, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from PRD_MDATE_ADJUST PMAD, FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO_AUTHORITY PPA, FIN_PRODUCT FP LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FP.FINPROD_ID = PMSI.FINPROD_ID where FP.FINPROD_ID = PMAD.FINPROD_ID and FP.FINPROD_ID = FPA.FINPROD_ID
and FPA.PORTFOLIO_ID = PPA.PORTFOLIO_ID and PPA.USER_ID = #{userId} and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} and FPA.ISSUE_STATUS = #{ISSUE_STATUS01}
and FP.FINPROD_ID IN
#{item}
and PMAD.MDATE >= to_date(#{adjustAfterMdateStart}, 'yyyy-MM-dd')
and PMAD.MDATE <= to_date(#{adjustAfterMdateEnd}, 'yyyy-MM-dd')
and PMAD.ADJUST_TYPE = #{adjustType}
AND NVL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
